// {ItemBlockPredicateBlockSet registryEntryHolderSet  0xc0004307d0}
type ItemBlockPredicateBlockSet struct {
	// RegistryEntryHolderSet can hold either named tags or numeric IDs
	IsTagList bool
	Tags      models.Array[pk.VarInt, string]
	IDs       models.Array[pk.VarInt, pk.VarInt]
}

func (r *ItemBlockPredicateBlockSet) ReadFrom(reader io.Reader) (int64, error) {
	var totalBytes int64

	// Read the varint count - if 0, tag list follows; otherwise IDs follow
	var count pk.VarInt
	n, err := count.ReadFrom(reader)
	totalBytes += n
	if err != nil {
		return totalBytes, err
	}

	if count == 0 {
		// Tag list representation
		r.IsTagList = true
		n, err = r.Tags.ReadFrom(reader)
		totalBytes += n
		if err != nil {
			return totalBytes, err
		}
	} else {
		// IDs list representation - count already read, now read count-1 more IDs
		r.IsTagList = false
		ary := make([]pk.VarInt, count)
		ary[0] = pk.VarInt(count - 1)
		for i := 1; i < int(count); i++ {
			var id pk.VarInt
			n, err := id.ReadFrom(reader)
			totalBytes += n
			if err != nil {
				return totalBytes, err
			}
			ary[i] = id
		}
		r.IDs.Ary.Ary = any(ary)
	}

	return totalBytes, nil
}

func (r ItemBlockPredicateBlockSet) WriteTo(w io.Writer) (int64, error) {
	var totalBytes int64

	if r.IsTagList {
		// Write 0 followed by tag list
		var zero pk.VarInt = 0
		n, err := zero.WriteTo(w)
		totalBytes += n
		if err != nil {
			return totalBytes, err
		}
		n, err = r.Tags.WriteTo(w)
		totalBytes += n
		return totalBytes, err
	} else {
		// Write IDs (with first ID + 1 as the "count")
		idsAry, ok := r.IDs.Ary.Ary.([]pk.VarInt)
		if !ok || len(idsAry) == 0 {
			return totalBytes, nil
		}
		// Write first ID + 1
		firstPlusOne := pk.VarInt(idsAry[0]) + 1
		n, err := firstPlusOne.WriteTo(w)
		totalBytes += n
		if err != nil {
			return totalBytes, err
		}
		// Write remaining IDs
		for i := 1; i < len(idsAry); i++ {
			n, err := idsAry[i].WriteTo(w)
			totalBytes += n
			if err != nil {
				return totalBytes, err
			}
		}
	}

	return totalBytes, nil
}

